#!/usr/bin/env bash
# Question 9: Token for a ServiceAccount. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/token
mkdir -p /opt/course/token
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q9_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q9_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q9_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q9_NS}" delete serviceaccount ci --ignore-not-found >/dev/null
kubectl -n "${Q9_NS}" create serviceaccount ci >/dev/null
: "${Q9_NS}" "${Q9_NODE}"
